-- Generated from learning/grammar-seeds.ts. Do not edit by hand.
-- Regenerate with: pnpm curriculum:generate
--
-- Shared reference content: what the tutor quotes when it corrects
-- somebody. common_mistakes carries the wrong form and the right one, so
-- a correction can name the exact sentence a learner keeps producing.

insert into public.grammar_patterns (key, name, explanation, examples, cefr, mini_level, difficulty, common_mistakes, related_pattern_keys)
values
  ('sein_present', 'Present tense of sein',
   'sein is irregular and the most common verb in German. Learn ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind as one block: almost every early sentence about who or what something is needs it.',
   array['Ich bin Lehrerin.', 'Wir sind aus Indien.', 'Bist du müde?']::text[],
   'A1', 1, 1,
   array['*Ich bin eine Lehrerin → Ich bin Lehrerin. German drops the article before a profession.', '*Du bin müde → Du bist müde.']::text[],
   array['personal_pronouns_nominative', 'haben_present']::text[]),
  ('personal_pronouns_nominative', 'Personal pronouns in the nominative',
   'ich, du, er, sie, es, wir, ihr, sie and Sie. The one to watch is sie: lower case it means she or they, capitalised in the middle of a sentence it means the formal you.',
   array['Er kommt aus Berlin.', 'Wie heißen Sie?', 'Wir wohnen in Köln.']::text[],
   'A1', 1, 1,
   array['*Sie heißt Herr Weber → Er heißt Herr Weber.', '*Du sind Frau Weber → Sie sind Frau Weber, if you are being formal.']::text[],
   array['sein_present', 'regular_verb_present']::text[]),
  ('regular_verb_present', 'Regular verb endings in the present tense',
   'Take the stem and add -e, -st, -t, -en, -t, -en. Most German verbs work this way, so once the endings are automatic a very large number of verbs come free.',
   array['Ich wohne in Hamburg.', 'Wohnst du hier?', 'Sie arbeiten viel.']::text[],
   'A1', 2, 1,
   array['*Er wohne in Berlin → Er wohnt in Berlin.', '*Ich arbeitst → Ich arbeite. The -st ending belongs to du.']::text[],
   array['verb_position_second', 'sein_present']::text[]),
  ('w_questions', 'Questions with wer, wo, was and wie',
   'Question word first, conjugated verb straight after it, then the subject. wer asks about people, was about things, wo about place, wie about manner.',
   array['Wo wohnst du?', 'Was machst du?', 'Wie heißt sie?']::text[],
   'A1', 2, 1,
   array['*Wo du wohnst? → Wo wohnst du? The verb comes straight after the question word.', '*Wer ist das, das Buch? → Was ist das? wer is only for people.']::text[],
   array['yes_no_questions', 'verb_position_second']::text[]),
  ('numbers_0_100', 'Numbers up to one hundred',
   'Above twenty the unit is said before the ten and joined with und, so 21 is einundzwanzig. It reads backwards to an English speaker and stays awkward until it is drilled.',
   array['Ich bin einundzwanzig Jahre alt.', 'Das kostet sechsundneunzig Euro.', 'Wir treffen uns um sieben.']::text[],
   'A1', 3, 1,
   array['*zwanzigeins → einundzwanzig. The unit comes first, joined by und.', '*siebenzehn → siebzehn. sieben loses its -en in 17 and 70.']::text[],
   array['wie_viel_questions']::text[]),
  ('yes_no_questions', 'Yes-or-no questions with the verb in first place',
   'With no question word the conjugated verb moves to the front. Raising your voice at the end of a statement is understood but marks you out as a beginner.',
   array['Kommst du mit?', 'Ist das dein Buch?', 'Habt ihr Zeit?']::text[],
   'A1', 3, 1,
   array['*Du kommst mit? → Kommst du mit?', '*Hast Zeit du? → Hast du Zeit?']::text[],
   array['w_questions', 'verb_position_second']::text[]),
  ('definite_articles_nominative', 'Der, die and das in the nominative',
   'der for masculine, die for feminine, das for neuter, die for all plurals. The article is part of the word: learn der Tisch, never Tisch on its own.',
   array['Der Tisch ist neu.', 'Die Tür ist offen.', 'Das Fenster ist groß.']::text[],
   'A1', 4, 1,
   array['*Die Tisch ist neu → Der Tisch ist neu.', '*Das Tür → Die Tür.']::text[],
   array['noun_gender', 'indefinite_article_accusative']::text[]),
  ('noun_gender', 'Gender that comes with each noun',
   'Gender is mostly not guessable, but some endings are reliable: -ung, -heit, -keit, -schaft and -ion are feminine; -chen and -lein are neuter; -er for a person doing something is masculine.',
   array['die Wohnung, die Freiheit, die Möglichkeit', 'das Mädchen, das Brötchen', 'der Lehrer, der Bäcker']::text[],
   'A1', 4, 1,
   array['*der Wohnung → die Wohnung. Nouns in -ung are feminine.', '*die Mädchen → das Mädchen. Every -chen word is neuter, whatever it means.']::text[],
   array['definite_articles_nominative', 'plural_nouns']::text[]),
  ('haben_present', 'Present tense of haben',
   'ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie haben. Beyond possession it is half of the Perfekt, so it is worth being fast with.',
   array['Ich habe keine Zeit.', 'Hast du Hunger?', 'Wir haben ein Auto.']::text[],
   'A1', 5, 1,
   array['*Er habt → Er hat.', '*Ich habe kein Zeit → Ich habe keine Zeit.']::text[],
   array['sein_present', 'indefinite_article_accusative', 'perfekt_with_haben']::text[]),
  ('indefinite_article_accusative', 'Ein and eine in the accusative',
   'ein, eine, ein as a subject; as a direct object only the masculine changes, to einen. kein takes exactly the same endings.',
   array['Ich habe einen Bruder.', 'Sie kauft eine Tasche.', 'Wir brauchen ein Buch.']::text[],
   'A1', 5, 1,
   array['*Ich habe ein Bruder → Ich habe einen Bruder.', '*Sie kauft einen Tasche → Sie kauft eine Tasche. Only the masculine changes.']::text[],
   array['accusative_case_objects', 'definite_articles_nominative']::text[]),
  ('possessive_articles_nominative', 'Mein, dein and ihr in the nominative',
   'mein, dein, sein, ihr, unser, euer, ihr and Ihr. They take the same endings as ein, so the ending follows the thing owned, not the owner.',
   array['Mein Bruder wohnt in Bonn.', 'Meine Schwester ist Ärztin.', 'Ist das dein Schlüssel?']::text[],
   'A1', 6, 1,
   array['*Mein Schwester → Meine Schwester.', '*Sein Mutter → Seine Mutter. The ending follows Mutter, not the son.']::text[],
   array['definite_articles_nominative', 'noun_gender']::text[]),
  ('plural_nouns', 'Plural forms of common nouns',
   'Five main patterns: -e, -er, -(e)n, -s and no ending, often with an umlaut. There is no shortcut, so the plural is learnt with the word and the article, as a set of three.',
   array['der Tisch → die Tische', 'das Buch → die Bücher', 'die Frau → die Frauen']::text[],
   'A1', 6, 1,
   array['*die Buches → die Bücher.', '*die Frauens → die Frauen. Only a few loanwords take -s.']::text[],
   array['noun_gender', 'definite_articles_nominative']::text[]),
  ('verb_position_second', 'Verb in second place',
   'The conjugated verb is the second element of a main clause, not the second word. Whatever you put first, the verb holds its place and the subject moves behind it.',
   array['Ich fahre morgen nach Köln.', 'Morgen fahre ich nach Köln.', 'Nach Köln fahre ich morgen.']::text[],
   'A1', 7, 1,
   array['*Morgen ich fahre nach Köln → Morgen fahre ich nach Köln.', '*Heute wir gehen ins Kino → Heute gehen wir ins Kino.']::text[],
   array['word_order_main_clause', 'w_questions']::text[]),
  ('gern_with_verbs', 'Gern to say what you like doing',
   'gern is not a verb. It sits after the conjugated verb and turns any activity into one you enjoy, which is how German usually says I like doing something.',
   array['Ich koche gern.', 'Er spielt gern Fußball.', 'Trinkst du gern Kaffee?']::text[],
   'A1', 7, 1,
   array['*Ich gern koche → Ich koche gern.', '*Ich mag kochen gern → Ich koche gern. Use one or the other, not both.']::text[],
   array['verb_position_second']::text[]),
  ('moechten_present', 'Ich möchte for ordering and asking',
   'ich möchte, du möchtest, er möchte, wir möchten. It is the polite way to ask for anything, and the main verb, if there is one, goes to the end in the infinitive.',
   array['Ich möchte einen Kaffee.', 'Möchten Sie etwas trinken?', 'Wir möchten bestellen.']::text[],
   'A1', 8, 1,
   array['*Ich will einen Kaffee → Ich möchte einen Kaffee. wollen sounds blunt when ordering.', '*Ich möchte einen Kaffee zu trinken → Ich möchte einen Kaffee trinken.']::text[],
   array['modal_verbs_koennen_muessen', 'accusative_case_objects']::text[]),
  ('accusative_case_objects', 'Accusative case on direct objects',
   'The thing the verb acts on takes the accusative. In practice only the masculine looks different: der becomes den and ein becomes einen. Everything else keeps its nominative form.',
   array['Ich sehe den Mann.', 'Sie liest das Buch.', 'Wir bestellen die Suppe.']::text[],
   'A1', 8, 1,
   array['*Ich sehe der Mann → Ich sehe den Mann.', '*Ich trinke der Kaffee → Ich trinke den Kaffee.']::text[],
   array['indefinite_article_accusative', 'dative_case_people', 'es_gibt']::text[]),
  ('wie_viel_questions', 'Questions with wie viel and wie viele',
   'wie viel for something you cannot count, wie viele for something you can. The same split as much and many in English, and it holds consistently.',
   array['Wie viel kostet das?', 'Wie viele Geschwister hast du?', 'Wie viel Zeit brauchst du?']::text[],
   'A1', 9, 1,
   array['*Wie viele kostet das? → Wie viel kostet das?', '*Wie viel Bücher hast du? → Wie viele Bücher hast du?']::text[],
   array['numbers_0_100']::text[]),
  ('separable_verbs', 'Separable verbs splitting around the sentence',
   'Verbs like aufstehen, ankommen and einsteigen split in a main clause: the verb is conjugated in second place and the prefix goes to the very end.',
   array['Ich stehe um sechs auf.', 'Wann kommt der Zug an?', 'Steig bitte vorne ein.']::text[],
   'A1', 10, 1,
   array['*Ich aufstehe um sechs → Ich stehe um sechs auf.', '*Ich habe angerufen dich → Ich habe dich angerufen.']::text[],
   array['verb_position_second', 'perfekt_with_haben']::text[]),
  ('time_expressions_um_am', 'Times with um, am and von … bis',
   'um for clock times, am for days and parts of the day, im for months and seasons. am and im are contractions of an dem and in dem, which is why they are dative.',
   array['Wir treffen uns um acht.', 'Am Montag habe ich frei.', 'Im Juli fahren wir weg.']::text[],
   'A1', 10, 1,
   array['*in Montag → am Montag.', '*am acht Uhr → um acht Uhr.']::text[],
   array['dative_prepositions_place']::text[]),
  ('dative_prepositions_place', 'Place prepositions taking the dative',
   'bei, zu, aus and von always take the dative, whether or not anything is moving. Watch the contractions: zu dem becomes zum, zu der becomes zur, bei dem becomes beim.',
   array['Ich bin bei der Arbeit.', 'Sie geht zum Arzt.', 'Wir kommen aus der Stadt.']::text[],
   'A1', 11, 1,
   array['*bei die Arbeit → bei der Arbeit.', '*zu dem Arzt → zum Arzt.']::text[],
   array['two_way_prepositions_static', 'dative_prepositions_fixed']::text[]),
  ('imperative_formal', 'Formal imperative with Sie',
   'Verb first, then Sie. Unlike the informal imperative the pronoun stays, which makes the formal command easy to build: take the Sie form and swap the two words round.',
   array['Gehen Sie geradeaus.', 'Nehmen Sie bitte Platz.', 'Warten Sie einen Moment.']::text[],
   'A1', 11, 1,
   array['*Sie gehen geradeaus → Gehen Sie geradeaus.', '*Gehen geradeaus → Gehen Sie geradeaus. The formal imperative keeps Sie.']::text[],
   array['imperative_informal', 'formal_register_sie']::text[]),
  ('es_gibt', 'Es gibt with the accusative',
   'es gibt is how German says there is and there are, and it never changes for number. Whatever follows it is a direct object, so it takes the accusative.',
   array['Hier gibt es einen Bahnhof.', 'Es gibt keinen Kaffee mehr.', 'Gibt es hier ein Café?']::text[],
   'A1', 12, 1,
   array['*Es gibt ein Bahnhof → Es gibt einen Bahnhof.', '*Es geben viele Cafés → Es gibt viele Cafés. It stays singular.']::text[],
   array['accusative_case_objects']::text[]),
  ('two_way_prepositions_static', 'Two-way prepositions answering wo',
   'in, an, auf, über, unter, vor, hinter, neben and zwischen take the dative when they answer wo, meaning nothing is moving from one place to another.',
   array['Das Buch liegt auf dem Tisch.', 'Wir sitzen im Garten.', 'Das Bild hängt über dem Sofa.']::text[],
   'A1', 12, 3,
   array['*Das Buch liegt auf den Tisch → auf dem Tisch.', '*In die Küche koche ich → In der Küche koche ich.']::text[],
   array['two_way_prepositions_motion', 'verbs_of_placement']::text[]),
  ('perfekt_with_haben', 'Perfekt with haben',
   'The everyday past tense in speech: haben conjugated in second place, past participle at the very end. Most verbs take haben.',
   array['Ich habe einen Film gesehen.', 'Wir haben gestern gekocht.', 'Hast du das gemacht?']::text[],
   'A1', 13, 1,
   array['*Ich habe gesehen einen Film → Ich habe einen Film gesehen.', '*Ich habe gegangen → Ich bin gegangen. Movement takes sein.']::text[],
   array['past_participles_regular', 'perfekt_with_sein']::text[]),
  ('past_participles_regular', 'Regular past participles with ge- … -t',
   'ge- plus the stem plus -t. Two groups take no ge- at all: verbs beginning with be-, ver-, er-, ent- or zer-, and verbs ending in -ieren.',
   array['machen → gemacht', 'kochen → gekocht', 'arbeiten → gearbeitet']::text[],
   'A1', 13, 1,
   array['*Ich habe gebestellt → Ich habe bestellt.', '*Ich habe gestudiert → Ich habe studiert. Verbs in -ieren take no ge-.']::text[],
   array['perfekt_with_haben', 'past_participles_irregular']::text[]),
  ('perfekt_with_sein', 'Perfekt with sein',
   'sein rather than haben for verbs of movement from one place to another and for a change of state, plus sein and bleiben themselves. The list is short enough to learn outright.',
   array['Ich bin nach Berlin gefahren.', 'Wir sind früh aufgestanden.', 'Sie ist eingeschlafen.']::text[],
   'A1', 14, 1,
   array['*Ich habe nach Berlin gefahren → Ich bin nach Berlin gefahren.', '*Ich bin einen Film gesehen → Ich habe einen Film gesehen.']::text[],
   array['perfekt_with_haben', 'past_participles_irregular']::text[]),
  ('past_participles_irregular', 'Irregular past participles',
   'Strong verbs take ge- plus a changed stem plus -en. There is no rule for the vowel change, so these are learnt as a list, and they are exactly the verbs used most often.',
   array['gehen → gegangen', 'fahren → gefahren', 'trinken → getrunken']::text[],
   'A1', 14, 1,
   array['*Ich habe getrinkt → Ich habe getrunken.', '*Ich bin gegeht → Ich bin gegangen.']::text[],
   array['past_participles_regular', 'perfekt_with_sein']::text[]),
  ('modal_verbs_koennen_muessen', 'Modal verbs können and müssen',
   'The modal is conjugated in second place and the main verb goes to the end as a bare infinitive, with no zu. Note that ich and er share a form: ich kann, er kann.',
   array['Ich kann heute nicht kommen.', 'Wir müssen früh aufstehen.', 'Kannst du mir helfen?']::text[],
   'A1', 15, 2,
   array['*Ich kann nicht kommen heute → Ich kann heute nicht kommen.', '*Ich muss zu arbeiten → Ich muss arbeiten. No zu after a modal.']::text[],
   array['modal_verb_wollen', 'modal_verb_sollen', 'verb_position_second']::text[]),
  ('negation_nicht_kein', 'Negation with nicht and kein',
   'kein negates a noun that would otherwise have ein or no article at all. nicht negates everything else, and normally stands just before whatever it is denying.',
   array['Ich habe kein Geld.', 'Das ist nicht mein Buch.', 'Ich komme heute nicht.']::text[],
   'A1', 15, 2,
   array['*Ich habe nicht Geld → Ich habe kein Geld.', '*Das ist kein mein Buch → Das ist nicht mein Buch.']::text[],
   array['indefinite_article_accusative']::text[]),
  ('dative_case_people', 'Dative case for the person affected',
   'The person something is given to, said to or done for takes the dative: dem, der, dem, den. Some verbs take it outright, notably helfen, danken, gehören, gefallen and antworten.',
   array['Ich helfe meinem Bruder.', 'Sie gibt der Kollegin das Buch.', 'Das gehört den Kindern.']::text[],
   'A2', 16, 3,
   array['*Ich helfe meinen Bruder → Ich helfe meinem Bruder. helfen takes the dative.', '*Das gehört den Kinder → den Kindern. The dative plural adds -n.']::text[],
   array['accusative_case_objects', 'dative_prepositions_fixed']::text[]),
  ('modal_verb_wollen', 'Modal verb wollen',
   'wollen is a stated intention, and it is stronger than English want. For requests it sounds abrupt, which is why möchten exists.',
   array['Ich will Deutsch lernen.', 'Willst du mitkommen?', 'Sie wollen umziehen.']::text[],
   'A2', 16, 2,
   array['*Ich will einen Kaffee, bitte → Ich möchte einen Kaffee, bitte.', '*Ich wille → Ich will. Modals take no ending in the ich form.']::text[],
   array['modal_verbs_koennen_muessen', 'moechten_present']::text[]),
  ('imperative_informal', 'Informal imperative with du and ihr',
   'For du, take the present tense form and drop the -st and the pronoun. For ihr, the present form is already the imperative. Strong verbs that change e to i keep the change.',
   array['Komm bitte her!', 'Nimm dir einen Stuhl.', 'Kommt rein!']::text[],
   'A2', 17, 2,
   array['*Kommst du her! → Komm her!', '*Gebe mir das → Gib mir das. geben changes its vowel.']::text[],
   array['imperative_formal', 'modal_particles']::text[]),
  ('modal_verb_sollen', 'Modal verb sollen for advice',
   'sollen reports an expectation that comes from somewhere else: advice, an instruction, what someone said you ought to do. It is not what you yourself want.',
   array['Du sollst mehr schlafen.', 'Der Arzt sagt, ich soll Sport machen.', 'Was soll ich tun?']::text[],
   'A2', 17, 2,
   array['*Ich soll einen Kaffee → Ich möchte einen Kaffee.', '*Du sollst zu gehen → Du sollst gehen.']::text[],
   array['modal_verbs_koennen_muessen', 'konjunktiv_ii_politeness']::text[]),
  ('comparative_forms', 'Comparative with -er and als',
   'Add -er and compare with als. Most short adjectives take an umlaut as well: alt becomes älter, groß becomes größer. gut, viel and gern are irregular.',
   array['Berlin ist größer als Bremen.', 'Der Zug ist schneller als der Bus.', 'Heute ist es wärmer.']::text[],
   'A2', 18, 2,
   array['*größer wie Bremen → größer als Bremen. wie is for things that are equal.', '*mehr groß → größer. German does not build comparatives with mehr.']::text[],
   array['superlative_forms', 'comparative_structures_je_desto']::text[]),
  ('subordinate_clause_weil', 'Weil clauses with the verb at the end',
   'weil sends the conjugated verb to the end of its clause. If the weil-clause comes first, the main clause then starts with its verb, because the whole clause counts as the first element.',
   array['Ich bleibe zu Hause, weil ich müde bin.', 'Sie lernt Deutsch, weil sie in Wien arbeitet.', 'Weil es regnet, nehme ich den Bus.']::text[],
   'A2', 18, 2,
   array['*weil ich bin müde → weil ich müde bin.', '*Weil es regnet, ich nehme den Bus → ..., nehme ich den Bus.']::text[],
   array['subordinate_clause_dass', 'word_order_main_clause']::text[]),
  ('two_way_prepositions_motion', 'Two-way prepositions answering wohin',
   'The same nine prepositions take the accusative when they answer wohin, meaning something crosses from one place into another. Direction is accusative, position is dative.',
   array['Ich gehe in die Küche.', 'Stell die Flasche auf den Tisch.', 'Er hängt das Bild über das Sofa.']::text[],
   'A2', 19, 3,
   array['*Ich gehe in der Küche → in die Küche, if you are moving there.', '*Stell das Buch auf dem Tisch → auf den Tisch.']::text[],
   array['two_way_prepositions_static', 'verbs_of_placement']::text[]),
  ('verbs_of_placement', 'Stellen, legen and hängen against stehen and liegen',
   'German splits putting from being. stellen, legen and hängen describe the act and take the accusative; stehen, liegen and hängen describe the result and take the dative.',
   array['Ich stelle die Flasche in den Kühlschrank.', 'Die Flasche steht im Kühlschrank.', 'Leg das Handtuch bitte ins Regal.']::text[],
   'A2', 19, 3,
   array['*Ich stehe die Flasche in den Kühlschrank → Ich stelle die Flasche hinein.', '*Das Buch legt auf dem Tisch → Das Buch liegt auf dem Tisch.']::text[],
   array['two_way_prepositions_motion', 'two_way_prepositions_static']::text[]),
  ('future_with_werden', 'Future with werden',
   'werden conjugated plus the infinitive at the end. German uses it less than English does: with a time word the present tense is the normal way to talk about the future.',
   array['Ich werde nächstes Jahr umziehen.', 'Es wird morgen regnen.', 'Wir werden dir helfen.']::text[],
   'A2', 20, 2,
   array['*Ich werde morgen zu arbeiten → Ich werde morgen arbeiten.', '*Ich werde morgen kommen is heavy → Ich komme morgen.']::text[],
   array['futur_ii', 'modal_verb_wollen']::text[]),
  ('subordinate_clause_wenn', 'Wenn clauses for conditions',
   'wenn introduces a condition and sends the verb to the end. Unlike English if, it also covers whenever, which is why als exists for single past events.',
   array['Wenn es regnet, bleiben wir zu Hause.', 'Ich rufe dich an, wenn ich ankomme.', 'Wenn du Zeit hast, komm vorbei.']::text[],
   'A2', 20, 2,
   array['*Wenn es regnet, wir bleiben zu Hause → ..., bleiben wir zu Hause.', '*Wann es regnet → Wenn es regnet. wann only asks a question.']::text[],
   array['temporal_clause_wenn', 'irreal_conditional_wenn', 'conditional_clauses_falls']::text[]),
  ('indirect_questions', 'Indirect questions inside a polite frame',
   'Wrap a question in a polite frame and it becomes a subordinate clause, so the verb goes to the end. This is the single most useful politeness move at a counter or on the phone.',
   array['Können Sie mir sagen, wo der Bahnhof ist?', 'Ich weiß nicht, wann der Zug kommt.', 'Wissen Sie, ob der Zug pünktlich ist?']::text[],
   'A2', 21, 2,
   array['*Können Sie mir sagen, wo ist der Bahnhof? → ..., wo der Bahnhof ist?', '*Ich weiß nicht, was ist das → ..., was das ist.']::text[],
   array['subordinate_clause_ob', 'w_questions']::text[]),
  ('subordinate_clause_ob', 'Ob clauses for reported yes-or-no questions',
   'ob reports a yes-or-no question and means whether. It is not interchangeable with wenn, which is a condition, even though English if covers both.',
   array['Ich weiß nicht, ob er kommt.', 'Sie fragt, ob wir Zeit haben.', 'Ob das stimmt, weiß niemand.']::text[],
   'A2', 21, 2,
   array['*Ich weiß nicht, wenn er kommt → ..., ob er kommt.', '*Sie fragt, ob haben wir Zeit → ..., ob wir Zeit haben.']::text[],
   array['indirect_questions', 'subordinate_clause_dass']::text[]),
  ('dative_prepositions_fixed', 'Mit, nach, von, zu, bei and seit with the dative',
   'mit, nach, von, zu, bei, seit, aus and außer always take the dative, with no exceptions and no wo-versus-wohin question to ask. Learn them as a chant.',
   array['Ich fahre mit dem Zug.', 'Nach der Arbeit gehe ich schwimmen.', 'Seit einem Jahr wohne ich hier.']::text[],
   'A2', 22, 2,
   array['*mit den Zug → mit dem Zug.', '*seit ein Jahr → seit einem Jahr.']::text[],
   array['dative_case_people', 'dative_prepositions_place']::text[]),
  ('temporal_clause_wenn', 'Wenn clauses for repeated events',
   'For something that happens repeatedly, in the present or the past, wenn is the right word and often carries immer. A single completed past event takes als instead.',
   array['Wenn ich Zeit habe, koche ich.', 'Immer wenn er kam, brachte er Blumen mit.', 'Wenn es schneit, steht die Stadt still.']::text[],
   'A2', 23, 2,
   array['*Als ich Zeit habe → Wenn ich Zeit habe. als is only for the past.', '*Wenn ich zwanzig wurde, zog ich nach Berlin → Als ich zwanzig wurde, ...']::text[],
   array['temporal_clause_als', 'subordinate_clause_wenn']::text[]),
  ('konjunktiv_ii_politeness', 'Würde and könnte for polite requests',
   'würde, könnte, hätte and wäre soften a request into something a stranger will happily answer. In service and office German this is the default register, not an extra.',
   array['Könnten Sie mir bitte helfen?', 'Ich hätte eine Frage.', 'Ich würde gern einen Termin vereinbaren.']::text[],
   'A2', 24, 2,
   array['*Ich will einen Termin → Ich hätte gern einen Termin.', '*Ich würde gern haben einen Termin → Ich hätte gern einen Termin.']::text[],
   array['konjunktiv_ii_present', 'formal_register_sie']::text[]),
  ('formal_register_sie', 'Sie register in writing',
   'Sie, Ihr and Ihnen are capitalised wherever they stand. A letter opens with Sehr geehrte Frau or Sehr geehrter Herr and closes with Mit freundlichen Grüßen.',
   array['Sehr geehrte Frau Weber, ich schreibe Ihnen wegen der Anzeige.', 'Könnten Sie mir Ihre Unterlagen schicken?', 'Mit freundlichen Grüßen']::text[],
   'A2', 24, 2,
   array['*Hallo Frau Weber, kannst du ... → Sehr geehrte Frau Weber, könnten Sie ...', '*ihre Unterlagen, meaning yours → Ihre Unterlagen with a capital.']::text[],
   array['imperative_formal', 'konjunktiv_ii_politeness']::text[]),
  ('subordinate_clause_dass', 'Dass clauses after saying and thinking',
   'dass reports what someone says, thinks or feels and sends the verb to the end. The comma before it is not optional in German.',
   array['Ich glaube, dass er recht hat.', 'Sie sagt, dass sie später kommt.', 'Es ist schade, dass du nicht kommst.']::text[],
   'A2', 25, 2,
   array['*Ich glaube, dass er hat recht → ..., dass er recht hat.', '*Ich glaube dass er recht hat → Ich glaube, dass er recht hat.']::text[],
   array['subordinate_clause_weil', 'indirect_speech_konjunktiv_i']::text[]),
  ('adjective_endings_definite', 'Adjective endings after der, die and das',
   'After der, die, das and their forms the adjective takes -e in the nominative singular and in the neuter and feminine accusative, and -en everywhere else. Five slots take -e, the rest take -en.',
   array['der neue Tisch', 'Ich sehe den neuen Tisch.', 'mit dem neuen Tisch']::text[],
   'A2', 26, 4,
   array['*der neuer Tisch → der neue Tisch.', '*Ich sehe den neue Tisch → den neuen Tisch.']::text[],
   array['adjective_endings_indefinite', 'accusative_case_objects']::text[]),
  ('adjective_endings_indefinite', 'Adjective endings after ein and kein',
   'ein shows no gender in three slots, so the adjective has to: ein neuer Tisch, ein neues Buch. Where the article does show it, the adjective falls back on -e or -en.',
   array['ein neuer Tisch', 'eine neue Tasche', 'ein neues Buch']::text[],
   'A2', 27, 4,
   array['*ein neue Tisch → ein neuer Tisch.', '*Ich habe einen neue Tisch → einen neuen Tisch.']::text[],
   array['adjective_endings_definite', 'indefinite_article_accusative']::text[]),
  ('modal_verb_duerfen', 'Modal verb dürfen',
   'dürfen is permission, not ability. Darf ich asks whether something is allowed; Kann ich asks whether it is possible, and mixing them is a common English habit.',
   array['Darf ich hier rauchen?', 'Hier darf man nicht parken.', 'Sie dürfen die Jacke umtauschen.']::text[],
   'A2', 27, 2,
   array['*Kann ich hier rauchen? → Darf ich hier rauchen?', '*Ich darf nicht zu rauchen → Ich darf nicht rauchen.']::text[],
   array['modal_verbs_koennen_muessen', 'impersonal_man']::text[]),
  ('reflexive_verbs_accusative', 'Reflexive verbs with the accusative pronoun',
   'mich, dich, sich, uns, euch, sich. With verbs like sich freuen, sich setzen and sich treffen the pronoun is part of the verb, not an optional extra.',
   array['Ich freue mich auf den Sommer.', 'Setz dich bitte.', 'Wir treffen uns um acht.']::text[],
   'A2', 29, 3,
   array['*Ich freue auf den Sommer → Ich freue mich auf den Sommer.', '*Ich freue mir → Ich freue mich. freuen takes the accusative.']::text[],
   array['verbs_with_prepositions', 'separable_verbs']::text[]),
  ('verbs_with_prepositions', 'Verbs with a fixed preposition',
   'Many verbs keep a fixed preposition that does not translate: warten auf, denken an, sich freuen über. The preposition also fixes the case, so the pair is learnt together.',
   array['Ich warte auf den Bus.', 'Sie denkt an ihre Familie.', 'Wir sprechen über die Arbeit.']::text[],
   'A2', 30, 3,
   array['*Ich warte für den Bus → Ich warte auf den Bus.', '*Ich denke über dich, meaning I am thinking of you → Ich denke an dich.']::text[],
   array['da_wo_compounds', 'reflexive_verbs_accusative']::text[]),
  ('da_wo_compounds', 'Da- and wo- compounds',
   'When the object of a fixed preposition is a thing rather than a person, German fuses the two: darauf, damit, davon. The question form does the same: worauf, womit.',
   array['Ich warte darauf.', 'Worauf wartest du?', 'Damit bin ich einverstanden.']::text[],
   'A2', 30, 3,
   array['*Ich warte auf es → Ich warte darauf.', '*Auf was wartest du? → Worauf wartest du? in careful German.']::text[],
   array['verbs_with_prepositions']::text[]),
  ('praeteritum_common_verbs', 'Präteritum of war, hatte and the modals',
   'war, hatte and the modals are used in the Präteritum even in speech, where other verbs would take the Perfekt. Getting these five or six right sounds instantly more natural.',
   array['Ich war gestern krank.', 'Wir hatten keine Zeit.', 'Er konnte nicht kommen.']::text[],
   'A2', 31, 3,
   array['*Ich bin gestern krank gewesen → Ich war gestern krank.', '*Ich habe nicht kommen gekonnt → Ich konnte nicht kommen.']::text[],
   array['praeteritum_vs_perfekt', 'temporal_clause_als']::text[]),
  ('temporal_clause_als', 'Als for a single event in the past',
   'als marks one completed event or one stretch of time in the past. If it happened repeatedly, or if it is not in the past, the word is wenn.',
   array['Als ich klein war, wohnten wir in Kiel.', 'Als der Zug ankam, regnete es.', 'Ich war zwanzig, als ich nach Berlin zog.']::text[],
   'A2', 31, 3,
   array['*Wenn ich klein war → Als ich klein war.', '*Als ich Zeit habe → Wenn ich Zeit habe.']::text[],
   array['temporal_clause_wenn', 'praeteritum_common_verbs']::text[]),
  ('superlative_forms', 'Superlative with am … -sten',
   'Standing alone after a verb, the superlative is am schnellsten. Before a noun it behaves like an ordinary adjective: der schnellste Zug. gut and viel are irregular.',
   array['Der Zug ist am schnellsten.', 'Das ist die beste Lösung.', 'Im Juli ist es am wärmsten.']::text[],
   'A2', 32, 3,
   array['*Der Zug ist der schnellste, with no noun → Der Zug ist am schnellsten.', '*am gutsten → am besten.']::text[],
   array['comparative_forms']::text[]),
  ('subordinate_clause_obwohl', 'Obwohl for conceding a point',
   'obwohl concedes a point and sends the verb to the end. It is the subordinate counterpart of trotzdem, and using both in one sentence is a common overcorrection.',
   array['Obwohl es regnete, sind wir gelaufen.', 'Ich mag die Stadt, obwohl sie laut ist.', 'Obwohl er müde war, arbeitete er weiter.']::text[],
   'A2', 32, 3,
   array['*obwohl es regnete, wir sind gelaufen → ..., sind wir gelaufen.', '*Obwohl es regnete, trotzdem sind wir gelaufen → pick one of the two.']::text[],
   array['concessive_connectors', 'connectors_deshalb_trotzdem']::text[]),
  ('passive_present', 'Passive in the present',
   'werden conjugated plus the past participle at the end. German uses the passive far more than English in signs, rules and descriptions of how things are done.',
   array['Der Müll wird dienstags abgeholt.', 'Hier wird nicht geraucht.', 'Die Formulare werden online ausgefüllt.']::text[],
   'A2', 33, 3,
   array['*Der Müll ist abgeholt, meaning it happens regularly → Der Müll wird abgeholt.', '*Der Müll wird abholen → Der Müll wird abgeholt.']::text[],
   array['passive_with_von_durch', 'passive_past', 'impersonal_man']::text[]),
  ('impersonal_man', 'Man for what people generally do',
   'man means one or people in general and always takes the third person singular. It is not the noun Mann, and it is the everyday alternative to the passive.',
   array['Hier darf man nicht parken.', 'In Deutschland trennt man den Müll.', 'Wie sagt man das auf Deutsch?']::text[],
   'A2', 33, 3,
   array['*Man sind → Man ist.', '*Mann trennt den Müll → Man trennt den Müll.']::text[],
   array['passive_present', 'modal_verb_duerfen']::text[]),
  ('genitive_case', 'Genitive case',
   'des and der, with -s or -es added to masculine and neuter nouns. Speech often replaces it with von plus the dative, but writing and set phrases keep it.',
   array['Das Auto meines Bruders steht draußen.', 'Die Farbe der Wand gefällt mir.', 'Wegen des Wetters bleiben wir hier.']::text[],
   'A2', 34, 4,
   array['*Das Auto meinem Bruder → Das Auto meines Bruders.', '*Wegen dem Wetter → wegen des Wetters. The dative is normal in speech, but writing keeps the genitive.']::text[],
   array['dative_case_people', 'nominalisation']::text[]),
  ('subordinate_clause_damit', 'Damit for purpose',
   'damit gives a purpose when the two halves have different subjects. When the subject is the same in both, German prefers um plus zu plus the infinitive.',
   array['Ich spreche langsam, damit du mich verstehst.', 'Sie spart, damit ihre Tochter studieren kann.', 'Damit nichts passiert, prüfen wir alles zweimal.']::text[],
   'A2', 34, 3,
   array['*damit du mich verstehen kannst is fine, but *damit du mich verstehst kannst → damit du mich verstehst.', '*Ich lerne, damit ich Deutsch spreche → Ich lerne, um Deutsch zu sprechen.']::text[],
   array['purpose_clause_um_zu']::text[]),
  ('connectors_deshalb_trotzdem', 'Deshalb and trotzdem joining two ideas',
   'deshalb, deswegen, darum and trotzdem join two main clauses. They count as the first element, so the verb comes straight after them and the subject moves behind it.',
   array['Es regnete, deshalb blieben wir zu Hause.', 'Es war teuer, trotzdem habe ich es gekauft.', 'Der Zug fiel aus, deswegen kam ich zu spät.']::text[],
   'A2', 35, 3,
   array['*deshalb wir blieben zu Hause → deshalb blieben wir zu Hause.', '*Weil es regnete, deshalb blieben wir → use weil or deshalb, not both.']::text[],
   array['word_order_main_clause', 'subordinate_clause_weil', 'concessive_connectors']::text[]),
  ('word_order_main_clause', 'Word order in the main clause',
   'The verb is second and the rest follows time, then manner, then place. Pronouns come early, and the accusative pronoun goes before the dative one.',
   array['Ich fahre morgen mit dem Zug nach Köln.', 'Morgen fahre ich mit dem Zug nach Köln.', 'Ich habe es ihr gestern gesagt.']::text[],
   'A2', 35, 3,
   array['*Ich fahre nach Köln morgen → Ich fahre morgen nach Köln.', '*Gestern ich habe es ihr gesagt → Gestern habe ich es ihr gesagt.']::text[],
   array['verb_position_second', 'connectors_deshalb_trotzdem']::text[]),
  ('opinion_phrases', 'Set phrases for stating an opinion',
   'Meiner Meinung nach, Ich finde, Ich halte etwas für and Aus meiner Sicht. Each one counts as the first element of the sentence, so the verb follows immediately.',
   array['Meiner Meinung nach ist das zu teuer.', 'Ich finde, dass man mehr tun müsste.', 'Ich halte den Vorschlag für sinnvoll.']::text[],
   'B1', 36, 3,
   array['*Meiner Meinung nach, das ist zu teuer → ... nach ist das zu teuer.', '*Ich denke so → Das sehe ich auch so.']::text[],
   array['subordinate_clause_dass', 'concessive_connectors']::text[]),
  ('concessive_connectors', 'Zwar … aber and dennoch for conceding',
   'zwar ... aber sets up a concession and then takes it back. dennoch and allerdings do the same job in one word, and all three keep the verb in second place.',
   array['Das Angebot ist zwar günstig, aber die Qualität stimmt nicht.', 'Er hat wenig Erfahrung, dennoch würde ich ihn nehmen.', 'Allerdings sehe ich ein Problem.']::text[],
   'B1', 37, 3,
   array['*Zwar es ist günstig → Zwar ist es günstig.', '*Obwohl es günstig ist, aber die Qualität stimmt nicht → drop the aber.']::text[],
   array['subordinate_clause_obwohl', 'connectors_deshalb_trotzdem', 'discourse_connectors']::text[]),
  ('modal_particles', 'Modal particles doch, ja and mal',
   'doch, ja, mal, eben and halt carry no dictionary meaning; they carry attitude. doch presses, ja shares surprise, mal softens. They sit just after the verb.',
   array['Komm doch mit!', 'Das ist ja interessant.', 'Warte mal kurz.']::text[],
   'B1', 37, 3,
   array['*Komm mit doch → Komm doch mit.', '*Das ist interessant ja → Das ist ja interessant.']::text[],
   array['imperative_informal']::text[]),
  ('praeteritum_vs_perfekt', 'Choosing between the Präteritum and the Perfekt',
   'Speech uses the Perfekt, writing and narration use the Präteritum. The exceptions run the other way: sein, haben and the modals take the Präteritum even in conversation.',
   array['Gestern habe ich meine Schwester getroffen.', 'Er ging zum Fenster und öffnete es.', 'Ich war müde und hatte keine Lust.']::text[],
   'B1', 38, 3,
   array['*Ich traf gestern meine Schwester, in conversation → Ich habe gestern meine Schwester getroffen.', '*Ich bin gestern krank gewesen → Ich war gestern krank.']::text[],
   array['praeteritum_common_verbs', 'plusquamperfekt']::text[]),
  ('plusquamperfekt', 'Plusquamperfekt for what happened first',
   'hatte or war plus the participle, for the thing that happened before the thing you are already telling. It pairs naturally with nachdem.',
   array['Nachdem wir gegessen hatten, gingen wir los.', 'Der Zug war schon abgefahren, als ich ankam.', 'Ich hatte den Schlüssel vergessen.']::text[],
   'B1', 38, 4,
   array['*Nachdem wir gegessen haben, gingen wir los → ... gegessen hatten, ...', '*Er war gegangen haben → Er war gegangen.']::text[],
   array['praeteritum_vs_perfekt', 'temporal_clause_als']::text[]),
  ('relative_clauses_nominative_accusative', 'Relative clauses in the nominative and accusative',
   'The relative pronoun looks like the definite article and takes its gender from the noun it refers back to, but its case from its job in the relative clause. The verb goes to the end.',
   array['Der Kollege, der neben mir sitzt, kommt aus Wien.', 'Das Buch, das ich gerade lese, ist spannend.', 'Die Frau, die du gesehen hast, ist meine Chefin.']::text[],
   'B1', 39, 4,
   array['*Der Kollege, der sitzt neben mir → ..., der neben mir sitzt.', '*Das Buch, was ich lese → Das Buch, das ich lese. was only follows alles, etwas or nichts.']::text[],
   array['relative_clauses_dative_genitive', 'relative_clauses_with_prepositions']::text[]),
  ('relative_clauses_dative_genitive', 'Relative clauses in the dative and genitive',
   'dem, der and denen when the verb inside the clause takes the dative; dessen and deren for possession. deren is feminine and plural, dessen masculine and neuter.',
   array['Der Kollege, dem ich geholfen habe, hat sich bedankt.', 'Die Nachbarn, denen wir den Schlüssel gaben, sind verreist.', 'Die Frau, deren Auto dort steht, wohnt hier.']::text[],
   'B1', 40, 5,
   array['*Der Kollege, den ich geholfen habe → dem ich geholfen habe. helfen takes the dative.', '*Die Frau, dessen Auto → deren Auto.']::text[],
   array['relative_clauses_nominative_accusative', 'genitive_case', 'dative_case_people']::text[]),
  ('relative_clauses_with_prepositions', 'Relative clauses after a preposition',
   'The preposition comes before the relative pronoun and decides its case. English can strand the preposition at the end; German never can.',
   array['Das Projekt, an dem ich arbeite, endet im Mai.', 'Die Kollegin, mit der ich spreche, ist neu.', 'Der Grund, aus dem er ging, war banal.']::text[],
   'B1', 40, 5,
   array['*Das Projekt, das ich arbeite an → ..., an dem ich arbeite.', '*Die Kollegin, die ich mit spreche → ..., mit der ich spreche.']::text[],
   array['relative_clauses_nominative_accusative', 'verbs_with_prepositions']::text[]),
  ('konjunktiv_ii_present', 'Konjunktiv II for wishes and hypotheses',
   'würde plus the infinitive covers most verbs. haben, sein and the modals keep their own forms, and using würde with them sounds clumsy: hätte, wäre, könnte, müsste.',
   array['Ich würde gern länger bleiben.', 'Wenn ich mehr Zeit hätte, würde ich reisen.', 'An deiner Stelle wäre ich vorsichtig.']::text[],
   'B1', 41, 4,
   array['*Ich würde mehr Zeit haben → Ich hätte mehr Zeit.', '*Wenn ich Zeit haben würde, würde ich reisen → Wenn ich Zeit hätte, würde ich reisen.']::text[],
   array['irreal_conditional_wenn', 'konjunktiv_ii_politeness']::text[]),
  ('irreal_conditional_wenn', 'Unreal conditions with wenn',
   'Both halves go into the Konjunktiv II. For something that did not happen in the past, use hätte or wäre plus the participle in both halves.',
   array['Wenn ich reich wäre, würde ich ein Haus kaufen.', 'Wenn du früher gegangen wärst, hättest du den Zug bekommen.', 'Hätte ich das gewusst, wäre ich geblieben.']::text[],
   'B1', 41, 5,
   array['*Wenn ich reich bin, würde ich ein Haus kaufen → Wenn ich reich wäre, ...', '*Wenn ich das gewusst hätte, hätte ich gekommen → ..., wäre ich gekommen.']::text[],
   array['konjunktiv_ii_present', 'subordinate_clause_wenn']::text[]),
  ('passive_with_von_durch', 'Passive with von and durch',
   'von names who did it and takes the dative; durch names what caused or carried it and takes the accusative. Most passive sentences name neither, which is the point of using one.',
   array['Das Formular wird von der Sachbearbeiterin geprüft.', 'Die Stadt wurde durch das Hochwasser beschädigt.', 'Der Vertrag wurde von beiden Seiten unterschrieben.']::text[],
   'B1', 43, 4,
   array['*durch die Sachbearbeiterin geprüft → von der Sachbearbeiterin. A person takes von.', '*von dem Hochwasser beschädigt → durch das Hochwasser.']::text[],
   array['passive_present', 'passive_past']::text[]),
  ('passive_with_modals', 'Passive with a modal verb',
   'The modal is conjugated, the participle comes next and werden goes last in the infinitive. This is the standard form of every rule, deadline and instruction in German bureaucracy.',
   array['Der Antrag muss bis Freitag eingereicht werden.', 'Das kann online erledigt werden.', 'Die Frist darf nicht überschritten werden.']::text[],
   'B1', 44, 4,
   array['*Der Antrag muss werden eingereicht → muss eingereicht werden.', '*Der Antrag muss eingereicht sein, if you mean the act → eingereicht werden.']::text[],
   array['passive_present', 'passive_past']::text[]),
  ('passive_past', 'Passive in the past',
   'wurde plus the participle in writing, or ist plus participle plus worden in speech. Note worden, not geworden: the passive drops the ge-.',
   array['Der Bahnhof wurde 1998 umgebaut.', 'Die Entscheidung ist gestern getroffen worden.', 'Mir wurde nichts gesagt.']::text[],
   'B1', 44, 4,
   array['*ist getroffen geworden → ist getroffen worden.', '*Der Bahnhof war umgebaut, meaning the event → Der Bahnhof wurde umgebaut.']::text[],
   array['passive_present', 'passive_with_von_durch']::text[]),
  ('indirect_speech_konjunktiv_i', 'Konjunktiv I for reported speech',
   'sei, habe, komme and so on report what someone said without endorsing it. Where the Konjunktiv I looks identical to the ordinary present, German falls back on the Konjunktiv II.',
   array['Er sagt, er sei krank.', 'Die Firma erklärte, sie habe nichts gewusst.', 'Sie behauptet, sie komme später.']::text[],
   'B1', 45, 5,
   array['*Er sagt, er ist krank, in a written report → er sei krank.', '*Sie sagen, sie haben nichts gewusst → sie hätten nichts gewusst.']::text[],
   array['reporting_verbs', 'subordinate_clause_dass']::text[]),
  ('reporting_verbs', 'Verbs that introduce reported speech',
   'sagen, erklären, betonen, behaupten and bestreiten each carry a different degree of commitment. behaupten and angeblich signal that the speaker does not vouch for it.',
   array['Er behauptet, davon nichts gewusst zu haben.', 'Die Zeitung berichtet, der Umbau verzögere sich.', 'Sie bestreitet jede Verantwortung.']::text[],
   'B1', 45, 4,
   array['*Er sagt zu mir, dass ... → Er sagt mir, dass ... sagen takes a plain dative.', '*Er behauptet zu wissen nichts → Er behauptet, nichts zu wissen.']::text[],
   array['indirect_speech_konjunktiv_i', 'infinitive_clauses_zu']::text[]),
  ('nominalisation', 'Turning verbs into nouns',
   'German turns verbs into nouns freely. A capitalised infinitive is always neuter: das Lesen, das Arbeiten. The -ung ending does the same job and is always feminine.',
   array['das Arbeiten von zu Hause', 'die Kündigung des Vertrags', 'Beim Lesen schlafe ich ein.']::text[],
   'B1', 46, 4,
   array['*die Arbeiten von zu Hause → das Arbeiten. A nominalised infinitive is neuter.', '*bei dem Lesen → beim Lesen.']::text[],
   array['genitive_case', 'infinitive_clauses_zu']::text[]),
  ('infinitive_clauses_zu', 'Infinitive clauses with zu',
   'zu plus the infinitive at the end of its clause, after verbs like vorhaben, vergessen and versuchen and after adjectives like wichtig and schwer. With a separable verb the zu sits inside: anzurufen.',
   array['Ich habe vor, ein Semester in Wien zu studieren.', 'Es ist wichtig, pünktlich zu sein.', 'Sie hat vergessen, mich anzurufen.']::text[],
   'B1', 48, 4,
   array['*Sie hat vergessen, mich zu anrufen → ..., mich anzurufen.', '*Ich habe vor zu studieren ein Semester → ..., ein Semester zu studieren.']::text[],
   array['purpose_clause_um_zu', 'nominalisation']::text[]),
  ('purpose_clause_um_zu', 'Um … zu for purpose',
   'um plus zu plus the infinitive states a purpose and has no subject of its own, so it only works when both halves share one. Otherwise the word is damit.',
   array['Ich lerne Deutsch, um hier zu arbeiten.', 'Um pünktlich zu sein, nehme ich den früheren Zug.', 'Sie spart, um ein Auto zu kaufen.']::text[],
   'B1', 48, 4,
   array['*Ich lerne Deutsch, um ich hier arbeite → ..., um hier zu arbeiten.', '*Ich spreche langsam, um du mich verstehst → ..., damit du mich verstehst.']::text[],
   array['subordinate_clause_damit', 'infinitive_clauses_zu']::text[]),
  ('conditional_clauses_falls', 'Falls and sofern for conditions',
   'falls and sofern mark a case that may well not arise, which is why they turn up in contracts and instructions. They behave exactly like wenn and send the verb to the end.',
   array['Falls Sie Fragen haben, rufen Sie uns an.', 'Sofern nichts dazwischenkommt, bin ich um sechs da.', 'Falls der Vertrag gekündigt wird, entfällt die Gebühr.']::text[],
   'B1', 51, 4,
   array['*Falls Sie Fragen haben, Sie rufen uns an → ..., rufen Sie uns an.', '*Falls, dass Sie Fragen haben → Falls Sie Fragen haben.']::text[],
   array['subordinate_clause_wenn', 'irreal_conditional_wenn']::text[]),
  ('comparative_structures_je_desto', 'Je … desto for linked change',
   'je plus a comparative sends its verb to the end; desto plus a comparative keeps its verb second. Two different word orders in one sentence, which is what makes it awkward.',
   array['Je früher wir anfangen, desto besser.', 'Je mehr ich lese, desto leichter fällt es mir.', 'Je länger die Laufzeit, desto niedriger die Rate.']::text[],
   'B1', 53, 4,
   array['*Je mehr ich lese, desto es fällt mir leichter → ..., desto leichter fällt es mir.', '*Je mehr ich lese, je leichter → ..., desto leichter.']::text[],
   array['comparative_forms', 'superlative_forms']::text[]),
  ('participles_as_adjectives', 'Participles used as adjectives',
   'Both participles can stand before a noun and then take ordinary adjective endings. The present participle in -end is active and ongoing; the past participle is finished or passive.',
   array['die steigenden Preise', 'ein gut ausgebautes Netz', 'die betroffenen Anwohner']::text[],
   'B1', 54, 4,
   array['*die steigende Preise → die steigenden Preise.', '*ein gut ausbauen Netz → ein gut ausgebautes Netz.']::text[],
   array['adjective_endings_definite', 'passive_past']::text[]),
  ('discourse_connectors', 'Connectors that structure a talk',
   'zunächst, außerdem, einerseits and andererseits, abschließend. They tell a listener where they are in your argument, and each counts as the first element, so the verb follows.',
   array['Zunächst möchte ich das Problem beschreiben.', 'Andererseits gibt es auch Vorteile.', 'Abschließend fasse ich kurz zusammen.']::text[],
   'B1', 68, 5,
